// Typed view of site/data/tutor.json, generated by `tutor site-data` from the
// verified sources (lesson keys, checker, hole map, explain goldens). The JSON is
// bundled at build time, so the site works from any static host with no fetch.
import raw from "../../site/data/tutor.json";

export interface Misconception {
  option: number; // 1-based
  id: string;
  feedback: string;
}

export interface Check {
  id: string;
  prompt: string;
  code: string;
  options: string[];
  answer: number; // 1-based
  hint: string;
  explanation: string;
  misconceptions: Misconception[];
}

export interface Lesson {
  id: string;
  title: string;
  kcs: string[];
  prerequisites: string[];
  verified_on: string;
  body: string;
  checks: Check[];
}

export interface Rule {
  id: string;
  name: string;
  kc: string;
  severity: "ADVICE" | "WARN" | "ERROR";
  fp_risk: string;
  measured_by: string;
  hints: string[];
  example: { code: string; message: string | null; line: number | null } | null;
}

export interface Hole {
  id: string;
  stage: number;
  kc: string;
  summary: string;
  file: string;
  spec: string;
  trivial_bodies: number;
}

export interface Fixture {
  name: string;
  hole: string;
  stage: number;
  misconception: string;
  description: string;
  expect_start: string;
  body: string;
  golden: string;
}

export interface Project {
  name: string;
  package: string;
  stages: number[];
  holes: Hole[];
  testsets: string[];
  deps: Record<string, string[]>;
  mutants: Record<string, { trivial: number; caught: boolean; failing_testsets: number }[]>;
  problems: string[];
  baseline: {
    allocations: Record<string, number>;
    inferred: Record<string, string>;
    bench_nodecount?: number;
    jet?: Record<string, string | number>;
  };
  fixtures: Fixture[];
}

export interface SiteData {
  julia: string;
  generated_by: string;
  lessons: Lesson[];
  rules: Rule[];
  projects: Project[];
}

export const data = raw as unknown as SiteData;

/** Testset names without the package prefix ("SymDiff/rewriting" -> "rewriting"). */
export const shortTestset = (t: string) => t.replace(/^[^/]+\//, "");
